// Revenue conversion module: triggers checkout offer when paidEvents=0
const axios = require('axios');

async function triggerConversionOffer() {
  try {
    // Simulate offering a discount to convert leads
    const response = await axios.post('http://localhost:4000/api/checkout/offer', {
      offer: { discount: 10, message: 'Complete your purchase now and save 10%!' }
    });
    console.log('Conversion offer sent:', response.data);
    return response.data;
  } catch (err) {
    console.error('Conversion offer failed:', err.message);
    return null;
  }
}

module.exports = { triggerConversionOffer };
